CREATE OR REPLACE FUNCTION calculate_sri(p_scanresolmm numeric, p_pointdense integer)
RETURNS numeric AS $$
BEGIN
    -- Handle NULL or non-positive inputs
    IF p_scanresolmm IS NULL OR p_pointdense IS NULL THEN
        RETURN NULL;
    END IF;

    -- Handle zero or negative values that would cause log errors
    IF p_scanresolmm <= 0 OR p_pointdense <= 1 THEN
        RETURN NULL;
    END IF;

    -- Calculate SRI = (log10(scanresolmm * 1000) / log10(pointdense)) * 5
    RETURN (LOG10(CAST(p_scanresolmm * 1000 AS numeric)) / LOG10(CAST(p_pointdense AS numeric))) * 5;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION sri_quality_category(p_sri numeric)
RETURNS text AS $$
BEGIN
    IF p_sri IS NULL THEN
        RETURN 'Unknown';
    ELSIF p_sri < 2.0 THEN
        RETURN 'Excellent';
    ELSIF p_sri < 3.0 THEN
        RETURN 'Good';
    ELSIF p_sri < 4.0 THEN
        RETURN 'Fair';
    ELSE
        RETURN 'Poor';
    END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

