CREATE OR REPLACE FUNCTION test_sri_functions(p_scanresolmm numeric, p_pointdense integer)
RETURNS TABLE(sri_value NUMERIC, quality_category TEXT) AS $$
BEGIN
    RETURN QUERY
    SELECT calculate_sri(p_scanresolmm, p_pointdense) AS sri_value,
           sri_quality_category(calculate_sri(p_scanresolmm, p_pointdense)) AS quality_category;
END;
$$ LANGUAGE plpgsql;
